    'gameTheory.battleAnalysis.coordination': 'Проблема координации: Главный вопрос — как игрокам договориться о том, какое именно равновесие реализовать. В реальности социальные нормы, коммуникация и фокальные точки (точки Шеллинга) помогают решить эту проблему.',
