    'gameTheory.pureESSDesc': 'Когда V ≥ C, стратегия «Ястреб» доминирует: даже при встрече двух ястребов ожидаемый выигрыш не хуже, чем у голубя. Популяция голубей не может вторгнуться.',
    'gameTheory.dominantStrategyNote.mixed': 'Ни одна стратегия не доминирует строго. Это приводит к смешанной ЭСС, где обе стратегии сосуществуют в определённой пропорции.',
    'gameTheory.dominantStrategyNote.pure': 'При данных параметрах Ястреб является доминирующей стратегией: даже в наихудшем случае (встреча с другим ястребом) выигрыш не хуже, чем у голубя.',
    'gameTheory.essReachedDesc': 'Доля ястребов стабилизируется около {percent}%. Начав с 50% ястребов, популяция сходится к равновесию, где фитнес обеих стратегий одинаков.',
    'gameTheory.hawksDominateDesc': 'Поскольку V ≥ C, доля ястребов стремится к 100%. Стратегия «Голубь» не может выжить в популяции.',
