    'gameTheory.evolutionAnalysis.model': 'Модель «Ястребы и Голуби» (Maynard Smith & Price, 1973) — первая эволюционная игра. Ястребы агрессивно борются за ресурс, голуби избегают конфликта. Результат встречи зависит от типа обоих участников.',
    'gameTheory.evolutionAnalysis.ess': 'ЭСС (Эволюционно стабильная стратегия): Стратегия, которая не может быть вытеснена никакой альтернативной стратегией при малом вторжении. Если V < C, то смешанная стратегия с долей ястребов p* = V/C является ЭСС.',
    'gameTheory.evolutionAnalysis.replicator': 'Репликаторная динамика: Доля стратегии в популяции растёт, если её фитнес выше среднего по популяции. Это приводит к сходимости к ЭСС из любого начального состояния (кроме краевых случаев).',
    'gameTheory.evolutionAnalysis.practical': 'Практическое значение: Модель объясняет, почему агрессия не вытесняет сотрудничество в природе. Если стоимость конфликта (C) превышает ценность ресурса (V), популяция стабилизируется с долей «голубей». Это основа для понимания эволюции альтруизма и кооперации.',

