    'adas.theory.adContent': 'Кривая AD показывает комбинации уровня цен и выпуска, при которых товарный и денежный рынки находятся в равновесии. Она имеет отрицательный наклон: при более высоком уровне цен реальный объём spending снижается. Сдвигается при изменении C, I, G, NX.',
    'adas.theory.srasTitle': 'Краткосрочное совокупное предложение (SRAS)',
    'adas.theory.srasContent': 'SRAS показывает объём выпуска, который фирмы готовы произвести при каждом уровне цен в краткосрочном периоде. Имеет положительный наклон: при более высоких ценах фирмы увеличивают выпуск. Сдвигается при изменении зарплат, цен сырья, производительности.',
    'adas.theory.lrasTitle': 'Долгосрочное совокупное предложение (LRAS)',
    'adas.theory.lrasContent': 'LRAS — вертикальная линия на уровне потенциального ВВП. В долгосрочном периоде выпуск определяется ресурсами и технологией, а не уровнем цен. Сдвигается при росте капитала, труда, технологическом прогрессе.',
    'adas.theory.equilibriumTitle': 'Краткосрочное и долгосрочное равновесие',
    'adas.theory.equilibriumContent': 'Краткосрочное равновесие — пересечение AD и SRAS. Если оно совпадает с LRAS, экономика в долгосрочном равновесии. Если нет — возникает инфляционный или рецессионный разрыв, который со временем устраняется через корректировку зарплат и цен.',
    'adas.theory.gapsTitle': 'Разрывы выпуска',
    'adas.theory.gapsContent': 'Инфляционный разрыв: фактический выпуск > потенциального (перегрев экономики). Рецессионный разрыв: фактический выпуск < потенциального (недоиспользование ресурсов). Потенциальный ВВП определяется технологиями, капиталом и трудом.',

