    // Theory
    'ppf.theory.whatIs': 'What the PPF Shows',
    'ppf.theory.whatIsContent': 'The production possibilities frontier (PPF) shows all combinations of maximum output of two goods with full utilization of available resources and a given level of technology. Every point on the curve represents an efficient choice for society.',
    'ppf.theory.increasingCost': 'Increasing Opportunity Cost',
    'ppf.theory.increasingCostContent': 'The PPF is concave to the origin because resources are not interchangeable. As output of one good increases, increasingly larger amounts of the other good must be sacrificed — this is the law of increasing opportunity cost.',
    'ppf.theory.growth': 'Economic Growth',
    'ppf.theory.growthContent': 'Economic growth shifts the PPF up and to the right: with more resources or improved technology, society can produce more of both goods. The shift may be asymmetric if technological progress affects only one industry.',
    'ppf.theory.efficiency': 'Efficiency and Inefficiency',
    'ppf.theory.efficiencyContent': 'Points on the PPF represent efficient production (all resources are employed). Points inside represent inefficiency (unemployment, underutilized capacity). Points outside are unattainable with current resources and technology, but may become available with economic growth.',

