    'gameTheory.prisonerAnalysis.title': 'Prisoner\'s Dilemma Analysis',
    'gameTheory.prisonerAnalysis.nash': 'Nash Equilibrium (mutual defection (-5, -5)): Neither player can improve their outcome by unilaterally changing strategy. If player 1 defects, player 2 is also better off defecting (-5 > -10). If player 1 cooperates, player 2 is still better off defecting (0 > -1). Thus, "Defect" is the dominant strategy.',
    'gameTheory.prisonerAnalysis.pareto': 'Pareto Optimum (mutual cooperation (-1, -1)): With mutual cooperation both players get a better outcome than with mutual defection (-1 > -5). However this state is unstable: each has an incentive to deviate and get 0 instead of -1.',
    'gameTheory.prisonerAnalysis.paradox': 'Paradox: Rational players pursuing self-interest arrive at a worse outcome for both. This is the core problem of game theory and the reason for the emergence of institutions, norms, and mechanisms to enforce cooperation.',
    'gameTheory.prisonerAnalysis.titForTat': 'Tit for Tat strategy: In repeated games, this simple strategy (cooperate first, then mirror the opponent\'s action) promotes cooperation and is one of the most successful in game theory tournaments.',
    'gameTheory.battleDesc': 'Player 1 prefers Opera, Player 2 prefers Football. Format: (Player 1, Player 2)',
    'gameTheory.opera': 'Opera',
    'gameTheory.football': 'Football',
    'gameTheory.interactiveGame': 'Interactive Game',
    'gameTheory.battleGameDesc': 'Choose strategies for both players and observe the result',
    'gameTheory.player1Pref': 'Player 1 (prefers Opera):',
    'gameTheory.player2Pref': 'Player 2 (prefers Football):',
    'gameTheory.playRound': 'Play Round',
    'gameTheory.mixedStrategy': 'Mixed Strategy',
    'gameTheory.mixedStrategyDesc': 'Mixed strategy equilibrium calculation',
    'gameTheory.expectedPayoffs': 'Expected payoffs in mixed equilibrium:',
    'gameTheory.note': 'Note:',
    'gameTheory.note.mixedPayoffs': 'In mixed equilibrium, expected payoffs ({p1}, {p2}) are lower than in any pure Nash equilibrium ((3, 2) or (2, 3)). This illustrates the coordination problem: players need to coordinate their actions to achieve a more favorable outcome for both.',
    'gameTheory.battleAnalysis': 'Battle of the Sexes Analysis',
    'gameTheory.battleAnalysis.pure': 'Pure Nash Equilibria: (Opera, Opera) and (Football, Football). In both cases players coordinate their actions, but the payoff distribution is unequal: one player gets more.',
    'gameTheory.battleAnalysis.mixed': 'Mixed Equilibrium: Each player randomizes with a certain probability, making the opponent indifferent to choice. This equilibrium is less efficient than pure ones, but doesn\'t require coordination.',
    'gameTheory.battleAnalysis.coordination': 'Coordination Problem: The key question is how players agree on which equilibrium to implement. In reality, social norms, communication, and focal points (Schelling points) help solve this problem.',
    'gameTheory.gameParams': 'Game Parameters',
    'gameTheory.paramsDesc': 'Set the resource value (V) and conflict cost (C)',
    'gameTheory.resourceValue': 'V — Resource Value',
    'gameTheory.conflictCost': 'C — Conflict Cost',
    'gameTheory.essExists': 'V < C → Evolutionarily Stable Strategy (ESS) exists',
    'gameTheory.hawksDominate': 'V ≥ C → Hawks dominate, ESS = all hawks',
    'gameTheory.dove': 'Dove',
    'gameTheory.hawk': 'Hawk',
    'gameTheory.shareResource': 'Share resource',
    'gameTheory.hawkTakesAll': 'Hawk takes all',
