    'gameTheory.fightButVC': 'Fight (but V≥C)',
    'gameTheory.essTitle': 'Evolutionarily Stable Strategy (ESS)',
    'gameTheory.mixedESS': 'Mixed ESS: hawk proportion = V/C',
    'gameTheory.hawkShare': 'Hawk share',
    'gameTheory.doveShare': 'Dove share',
    'gameTheory.pureESS': 'Pure ESS: all hawks',
    'gameTheory.pureESSDesc': 'When V ≥ C, the Hawk strategy dominates: even when two hawks meet, the expected payoff is no worse than a dove\'s. A dove population cannot invade.',
    'gameTheory.dominantStrategyNote.mixed': 'No strategy strictly dominates. This leads to a mixed ESS where both strategies coexist in a certain proportion.',
    'gameTheory.dominantStrategyNote.pure': 'With these parameters, Hawk is the dominant strategy: even in the worst case (meeting another hawk), the payoff is no worse than a dove\'s.',
    'gameTheory.essReachedDesc': 'Hawk proportion stabilizes around {percent}%. Starting from 50% hawks, the population converges to equilibrium where both strategies have equal fitness.',
    'gameTheory.hawksDominateDesc': 'Since V ≥ C, the hawk proportion tends toward 100%. The "Dove" strategy cannot survive in the population.',
    'gameTheory.dominantStrategy': 'Dominant strategy:',
    'gameTheory.populationSim': 'Population Simulation',
    'gameTheory.replicatorDesc': 'Replicator dynamics: starting hawk proportion = 50%, {generations} generations',
