    'gameTheory.dovesStart': 'Doves (start)',
    'gameTheory.hawksEnd': 'Hawks (end)',
    'gameTheory.dovesEnd': 'Doves (end)',
    'gameTheory.evolutionAnalysis': 'Evolutionary Game Analysis',
    'gameTheory.evolutionAnalysis.model': '"Hawks and Doves" model (Maynard Smith & Price, 1973) — the first evolutionary game. Hawks aggressively fight for resources, doves avoid conflict. The outcome depends on the type of both participants.',
    'gameTheory.evolutionAnalysis.ess': 'ESS (Evolutionarily Stable Strategy): A strategy that cannot be displaced by any alternative strategy upon small invasion. If V < C, then a mixed strategy with hawk proportion p* = V/C is the ESS.',
    'gameTheory.evolutionAnalysis.replicator': 'Replicator Dynamics: The proportion of a strategy in the population grows if its fitness is above the population average. This leads to convergence to the ESS from any initial state (except edge cases).',
    'gameTheory.evolutionAnalysis.practical': 'Practical Significance: The model explains why aggression does not displace cooperation in nature. If the cost of conflict (C) exceeds the resource value (V), the population stabilizes with a proportion of "doves". This is the basis for understanding the evolution of altruism and cooperation.',

