    'adas.theory.srasTitle': 'Short-Run Aggregate Supply (SRAS)',
    'adas.theory.srasContent': 'SRAS shows the output firms are willing to produce at each price level in the short run. It slopes upward: at higher prices firms increase output. It shifts when wages, input prices, or productivity change.',
    'adas.theory.lrasTitle': 'Long-Run Aggregate Supply (LRAS)',
    'adas.theory.lrasContent': 'LRAS is a vertical line at potential GDP. In the long run, output is determined by resources and technology, not the price level. It shifts with growth in capital, labor, or technological progress.',
    'adas.theory.equilibriumTitle': 'Short-Run and Long-Run Equilibrium',
    'adas.theory.equilibriumContent': 'Short-run equilibrium is the intersection of AD and SRAS. If it coincides with LRAS, the economy is in long-run equilibrium. If not, an inflationary or recessionary gap arises, which is eventually eliminated through wage and price adjustments.',
    'adas.theory.gapsTitle': 'Output Gaps',
