    'adas.theory.adTitle': '总需求 (AD)',
    'adas.theory.adContent': 'AD曲线显示商品和货币市场均衡时价格水平和产出的组合。它向下倾斜：更高的价格水平减少实际支出。当C、I、G或NX变化时移动。',
    'adas.theory.srasTitle': '短期总供给 (SRAS)',
    'adas.theory.srasContent': 'SRAS显示企业在短期内愿意在每个价格水平下生产的产出。它向上倾斜：在更高价格下企业增加产出。当工资、投入品价格或生产率变化时移动。',
    'adas.theory.lrasTitle': '长期总供给 (LRAS)',
    'adas.theory.lrasContent': 'LRAS是在潜在GDP处的垂直线。长期内，产出由资源和技术决定，而非价格水平。它随资本、劳动力或技术进步而移动。',
    'adas.theory.equilibriumTitle': '短期和长期均衡',
    'adas.theory.equilibriumContent': '短期均衡是AD和SRAS的交点。如果它与LRAS重合，经济处于长期均衡。如果不重合，则出现通胀或衰退缺口，最终通过工资和价格调整消除。',
    'adas.theory.gapsTitle': '产出缺口',
    'adas.theory.gapsContent': '通胀缺口：实际产出>潜在（经济过热）。衰退缺口：实际产出<潜在（资源未充分利用）。潜在GDP由技术、资本和劳动力决定。',
